    // GENERATED by cut/hsunits.py for region 4 of 0x1ea5c8 sphere_collide. DO NOT EDIT (the gate refuses a changed table; EDGE_OK is rewritten by `hsunits.py cov`).
    pub const ENTRY: u32 = 0x1ea5c8;
    pub const NB: usize = 1;
    pub const NE: usize = 2;
    /// EDGE_BLK value of an edge that leaves the region.
    pub const EXIT: usize = usize::MAX;
    /// Longest run of instructions between two due checks (region entry / loop header / return from a call).
    pub const MAX_SEG: u64 = 50;
    /// Instructions per block (delay slot included; a branch-likely that is not taken: `c.icount -= 1` after `blk`).
    pub static T: [u16; NB] = [50];
    pub static BLOCK_PC: [u32; NB] = [0x2e0];
    /// Edge e: target pc, target block (or EXIT).
    pub static EDGE_TO: [u32; NE] = [0x2e0, 0x3a8];
    pub static EDGE_BLK: [usize; NE] = [0, EXIT];
    /// Edges the corpus run exercised (measured by `hsregion cov`). Any other edge deopts: untested paths never go live.
    pub static EDGE_OK: [bool; NE] = [true, true];
    /// Leave the current block along edge `e`: returns the next block index (stay in the region) or returns from `region`
    /// (exit: pc/npc/now set) or deopts when the edge was never exercised. `c.icount` must already include the block (and
    /// the `-= 1` of a not-taken branch-likely). Needs a `flush!()` macro in scope (writes locals back; empty in plain style).
    macro_rules! go {
        ($c:expr, $fr:expr, $e:expr) => {{
            let e: usize = $e;
            if !super::gen::EDGE_OK[e] {
                flush!();
                return crate::hs::deopt($c, $fr, $fr.pc(super::gen::EDGE_TO[e]), $c.icount);
            }
            let nb = super::gen::EDGE_BLK[e];
            if nb == super::gen::EXIT {
                flush!();
                $c.pc = $fr.pc(super::gen::EDGE_TO[e]);
                $c.npc = $c.pc.wrapping_add(4);
                $c.mem.now = $c.icount;
                return true;
            }
            nb
        }};
    }
    
    /// Declared deopt stub (S2g): the block's Rust is NOT written; the block start deopts (`flush!()` first). Use it as the first statement of a block arm that the
