        let v0 = V::ld(c.vf[0]);
        let v2 = V::ld(c.vf[2]);
        let v3 = V::ld(c.vf[3]);
        let v6 = V::ld(c.vf[6]);
        let v21 = V::ld(c.vf[21]);
        let v22 = V::ld(c.vf[22]);
        let v23 = V::ld(c.vf[23]);
