        let mut v4 = V::ld(c.vf[4]);
        let mut v5 = V::ld(c.vf[5]);
        let mut v7 = V::ld(c.vf[7]);
        let mut v8 = V::ld(c.vf[8]);
        let mut v9 = V::ld(c.vf[9]);
        let mut v10 = V::ld(c.vf[10]);
        let mut v11 = V::ld(c.vf[11]);
        let mut v24 = V::ld(c.vf[24]);
        let mut v25 = V::ld(c.vf[25]);
        let mut v26 = V::ld(c.vf[26]);
        let mut v27 = V::ld(c.vf[27]);
        let mut v28 = V::ld(c.vf[28]);
        let mut v29 = V::ld(c.vf[29]);
