                wlo(c, 22, s6);
                c.vf[1] = v1.st();
                c.vf[4] = v4.st();
                c.vf[5] = v5.st();
                c.vf[7] = v7.st();
                c.vf[8] = v8.st();
                c.vf[9] = v9.st();
                c.vf[10] = v10.st();
                c.vf[11] = v11.st();
                c.vf[24] = v24.st();
                c.vf[25] = v25.st();
                c.vf[26] = v26.st();
                c.vf[27] = v27.st();
                c.vf[28] = v28.st();
                c.vf[29] = v29.st();
