                    let x = ld32!(c, fr, fm, (s4 as u32).wrapping_add(0xc), 1, fr.pc(0x958), ic0 + 1, 13);
                    set32!(at, x);
                    rearm!();
                    // 2 @0x95c lui $t5, 0x7000
                    set32!(t5, 0x7000_0000u32);
                    // 3 @0x960 lw $t6, 8($s4)
                    let x = ld32!(c, fr, fm, (s4 as u32).wrapping_add(8), 14, fr.pc(0x960), ic0 + 3, 11);
