                    rearm!();
                    // 4 @0x964 add $t7, $s4, $t3
                    set32!(t7, (s4 as u32).wrapping_add(t3 as u32));
                    // 5 @0x968 add $t7, $t7, $at
                    set32!(t7, (t7 as u32).wrapping_add(at as u32));
                    // 6 @0x96c lui $t3, 2
                    set32!(t3, 0x2_0000u32);
                    // 7 @0x970 lw $a1, ($t7)
                    let x = ld32!(c, fr, fm, t7 as u32, 5, fr.pc(0x970), ic0 + 7, 7);
                    set32!(a1, x);
                    rearm!();
                    // 8 @0x974 add $t6, $t6, $t7
                    set32!(t6, (t6 as u32).wrapping_add(t7 as u32));
