                    set64!(t3, (t3 as u64) | 0x202);
                    // 10 @0x97c ori $t4, $zero, 0x700
                    set64!(t4, 0x700u64);
                    // 11 @0x980 pcpyh $t4, $zero, $t4
                    t4 = mmi::pcpyh(t4);
                    // 12 @0x984 pextlb $a1, $t3, $a1
                    a1 = mmi::pextlb(t3, a1);
